SET time_zone = "+00:00";
SET NAMES utf8mb4;

-- Struktur Tabel `handover`
DROP TABLE IF EXISTS `handover`;
CREATE TABLE `handover` (
  `id` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `handoverNo` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `noPolisi` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `shift` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `status` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `type` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'mulai',
  `locationLat` double DEFAULT NULL,
  `locationLng` double DEFAULT NULL,
  `amt1` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `amt2` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `timestamp` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `notes` text COLLATE utf8mb4_unicode_ci,
  `userId` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `createdAt` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updatedAt` datetime(3) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `Handover_userId_fkey` (`userId`),
  KEY `handover_createdAt_status_noPolisi_idx` (`createdAt`,`status`,`noPolisi`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;











-- Struktur Tabel `issue`
DROP TABLE IF EXISTS `issue`;
CREATE TABLE `issue` (
  `id` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `handoverId` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `status` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'ONGOING',
  `resolvedAt` datetime(3) DEFAULT NULL,
  `repairRequestedAt` datetime(3) DEFAULT NULL,
  `resolvedBy` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `createdAt` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updatedAt` datetime(3) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `Issue_handoverId_key` (`handoverId`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Struktur Tabel `amt_issue`
DROP TABLE IF EXISTS `amt_issue`;
CREATE TABLE `amt_issue` (
  `id` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `handoverId` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `userId` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `amtName` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `amtRole` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT 'AMT_1',
  `itemName` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `category` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'B',
  `status` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'PENDING',
  `notes` text COLLATE utf8mb4_unicode_ci,
  `actionTaken` text COLLATE utf8mb4_unicode_ci,
  `resolvedAt` datetime(3) DEFAULT NULL,
  `resolvedBy` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `createdAt` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updatedAt` datetime(3) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `amt_issue_handoverId_idx` (`handoverId`),
  KEY `amt_issue_userId_idx` (`userId`),
  KEY `amt_issue_status_idx` (`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Struktur Tabel `handoveritem`
DROP TABLE IF EXISTS `handoveritem`;
CREATE TABLE `handoveritem` (
  `id` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `category` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `name` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `isGood` tinyint(1) NOT NULL,
  `handoverId` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `severity` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `notes` text COLLATE utf8mb4_unicode_ci,
  `repairNote` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `repairPhotoUrl` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `isRepaired` tinyint(1) NOT NULL DEFAULT '0',
  `adminRejectionNote` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `HandoverItem_handoverId_fkey` (`handoverId`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;






























































